import{_ as t,c as o,b as s,a as c,d as a,e as p,w as i,r as l,o as u}from"./app-BCUmHMw7.js";const r={};function d(k,n){const e=l("RouteLink");return u(),o("div",null,[n[3]||(n[3]=s("h1",{id:"clickhouse-queries",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#clickhouse-queries"},[s("span",null,"ClickHouse Queries")])],-1)),s("p",null,[n[1]||(n[1]=a("FluxaORM provides ClickHouse support for analytics, reporting, and direct SQL operations. For schema management, see ",-1)),p(e,{to:"/guide/clickhouse_schema.html"},{default:i(()=>n[0]||(n[0]=[a("ClickHouse Schema Management",-1)])),_:1,__:[0]}),n[2]||(n[2]=a(".",-1))]),n[4]||(n[4]=c(`<p>First, configure a ClickHouse pool and create an engine:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">import</span> fluxaorm <span class="token string">&quot;github.com/latolukasz/fluxaorm/v2&quot;</span></span>
<span class="line"></span>
<span class="line">registry <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewRegistry</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterClickhouse</span><span class="token punctuation">(</span><span class="token string">&quot;clickhouse://localhost:9000/default&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;analytics&quot;</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line">engine<span class="token punctuation">,</span> err <span class="token operator">:=</span> registry<span class="token punctuation">.</span><span class="token function">Validate</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">panic</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">ctx <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">NewContext</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="clickhouse-data-pool" tabindex="-1"><a class="header-anchor" href="#clickhouse-data-pool"><span>ClickHouse Data Pool</span></a></h2><p>Access the ClickHouse pool through <code>engine.Clickhouse()</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">ch <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Clickhouse</span><span class="token punctuation">(</span><span class="token string">&quot;analytics&quot;</span><span class="token punctuation">)</span></span>
<span class="line">config <span class="token operator">:=</span> ch<span class="token punctuation">.</span><span class="token function">GetConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">config<span class="token punctuation">.</span><span class="token function">GetCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span>          <span class="token comment">// &quot;analytics&quot;</span></span>
<span class="line">config<span class="token punctuation">.</span><span class="token function">GetDataSourceURI</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// &quot;clickhouse://localhost:9000/default&quot;</span></span>
<span class="line">config<span class="token punctuation">.</span><span class="token function">GetOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>       <span class="token comment">// *ClickhouseOptions with MaxOpenConnections, etc.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="clickhouse-interface-methods" tabindex="-1"><a class="header-anchor" href="#clickhouse-interface-methods"><span>Clickhouse Interface Methods</span></a></h2><p>The <code>Clickhouse</code> interface returned by <code>engine.Clickhouse(code)</code> provides the following methods:</p><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>GetConfig() ClickhouseConfig</code></td><td>Returns the ClickHouse pool configuration</td></tr><tr><td><code>GetDBClient() DBClient</code></td><td>Returns the underlying <code>database/sql</code> client</td></tr><tr><td><code>SetMockDBClient(mock DBClient)</code></td><td>Replaces the DB client with a mock (useful for testing)</td></tr><tr><td><code>Exec(ctx, query, args...) (ExecResult, error)</code></td><td>Executes a query (DDL, INSERT, etc.)</td></tr><tr><td><code>QueryRow(ctx, query Where, toFill...) (bool, error)</code></td><td>Queries a single row using a <code>Where</code> object, returns <code>false</code> if not found</td></tr><tr><td><code>Query(ctx, query, args...) (Rows, close, error)</code></td><td>Queries multiple rows</td></tr></tbody></table><p>Note that unlike the MySQL <code>DB</code> interface, <code>Clickhouse</code> does not support transactions.</p><h2 id="executing-queries" tabindex="-1"><a class="header-anchor" href="#executing-queries"><span>Executing Queries</span></a></h2><p>Use the <code>Exec()</code> method to run DDL statements and data modifications:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">ch <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Clickhouse</span><span class="token punctuation">(</span><span class="token string">&quot;analytics&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Create a table</span></span>
<span class="line"><span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> ch<span class="token punctuation">.</span><span class="token function">Exec</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">&quot;CREATE TABLE IF NOT EXISTS events (id UInt64, name String, ts DateTime) ENGINE = MergeTree() ORDER BY id&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Insert data</span></span>
<span class="line"><span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">=</span> ch<span class="token punctuation">.</span><span class="token function">Exec</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">&quot;INSERT INTO events (id, name, ts) VALUES (?, ?, ?)&quot;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token string">&quot;page_view&quot;</span><span class="token punctuation">,</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="querying-a-single-row" tabindex="-1"><a class="header-anchor" href="#querying-a-single-row"><span>Querying a Single Row</span></a></h2><p>Use <code>QueryRow()</code> to fetch a single row. Like the MySQL <code>DB.QueryRow</code>, this method takes a <code>Where</code> object for automatic parameter binding:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">ch <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Clickhouse</span><span class="token punctuation">(</span><span class="token string">&quot;analytics&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">var</span> count <span class="token builtin">uint64</span></span>
<span class="line">found<span class="token punctuation">,</span> err <span class="token operator">:=</span> ch<span class="token punctuation">.</span><span class="token function">QueryRow</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewWhere</span><span class="token punctuation">(</span><span class="token string">&quot;SELECT count() FROM events WHERE name = ?&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;page_view&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>count<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> found <span class="token punctuation">{</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Printf</span><span class="token punctuation">(</span><span class="token string">&quot;Page views: %d\\n&quot;</span><span class="token punctuation">,</span> count<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>If no row matches, <code>found</code> is <code>false</code> and <code>err</code> is <code>nil</code>.</p><h2 id="querying-multiple-rows" tabindex="-1"><a class="header-anchor" href="#querying-multiple-rows"><span>Querying Multiple Rows</span></a></h2><p>Use <code>Query()</code> to fetch multiple rows:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">ch <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Clickhouse</span><span class="token punctuation">(</span><span class="token string">&quot;analytics&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">var</span> id <span class="token builtin">uint64</span></span>
<span class="line"><span class="token keyword">var</span> name <span class="token builtin">string</span></span>
<span class="line">rows<span class="token punctuation">,</span> <span class="token builtin">close</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> ch<span class="token punctuation">.</span><span class="token function">Query</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">&quot;SELECT id, name FROM events ORDER BY id LIMIT 100&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> <span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> rows<span class="token punctuation">.</span><span class="token function">Next</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    err <span class="token operator">=</span> rows<span class="token punctuation">.</span><span class="token function">Scan</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>id<span class="token punctuation">,</span> <span class="token operator">&amp;</span>name<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The <code>Rows</code> interface returned by <code>Query()</code> provides:</p><ul><li><code>Next() bool</code> — advances to the next row, returns <code>false</code> when done.</li><li><code>Scan(dest ...any) error</code> — scans the current row into the provided variables.</li><li><code>Columns() ([]string, error)</code> — returns the column names.</li></ul><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Always include a <code>defer close()</code> after every <code>ch.Query()</code> call to release the underlying database connection.</p></div><h2 id="mocking-the-db-client" tabindex="-1"><a class="header-anchor" href="#mocking-the-db-client"><span>Mocking the DB Client</span></a></h2><p>For unit testing, you can replace the underlying database client with a mock:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">ch <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Clickhouse</span><span class="token punctuation">(</span><span class="token string">&quot;analytics&quot;</span><span class="token punctuation">)</span></span>
<span class="line">ch<span class="token punctuation">.</span><span class="token function">SetMockDBClient</span><span class="token punctuation">(</span>myMockClient<span class="token punctuation">)</span> <span class="token comment">// myMockClient must implement the DBClient interface</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div>`,25))])}const h=t(r,[["render",d]]),g=JSON.parse('{"path":"/guide/clickhouse_queries.html","title":"ClickHouse Queries","lang":"en-US","frontmatter":{},"git":{"updatedTime":1773759887000,"contributors":[{"name":"Lukasz Lato","username":"","email":"latolukasz@gmail.com","commits":3}],"changelog":[{"hash":"91d0cea838ff5bf0f6d59e2ce45b1c4c6c861026","time":1773759887000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"},{"hash":"d8084dc81a69db17ae668abfbcd731472f032b33","time":1773748837000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"},{"hash":"d37387037ceb80cb877582f020cc68130eb0ecf0","time":1773740845000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"}]},"filePathRelative":"guide/clickhouse_queries.md"}');export{h as comp,g as data};
